1	package com.example.starter.race.persistence;
2	
3	import com.example.starter.race.domain.EntryStatus;
4	import com.example.starter.race.domain.PenaltyType;
5	import com.example.starter.race.domain.RaceStatus;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.core.RowMapper;
8	import org.springframework.stereotype.Repository;
9	
10	import java.sql.ResultSet;
11	import java.sql.SQLException;
12	import java.util.List;
13	import java.util.Optional;
14	
15	/**
16	 * 赛事封榜领域的 JDBC 仓储；所有写方法均假定运行在业务事务内，
17	 * 版本推进与封榜全部使用条件 UPDATE 保证并发下无丢失更新。
18	 */
19	@Repository
20	public class RaceRepository {
21	
22	    private static final RaceRowMapper RACE_ROW_MAPPER = new RaceRowMapper();
23	    private static final RunnerRowMapper RUNNER_ROW_MAPPER = new RunnerRowMapper();
24	    private static final PenaltyRowMapper PENALTY_ROW_MAPPER = new PenaltyRowMapper();
25	    private static final SnapshotEntryRowMapper SNAPSHOT_ENTRY_ROW_MAPPER =
26	            new SnapshotEntryRowMapper();
27	    private static final IdempotencyRowMapper IDEMPOTENCY_ROW_MAPPER = new IdempotencyRowMapper();
28	    private static final CheckpointRowMapper CHECKPOINT_ROW_MAPPER = new CheckpointRowMapper();
29	    private static final CheckpointTimingRowMapper CHECKPOINT_TIMING_ROW_MAPPER =
30	            new CheckpointTimingRowMapper();
31	    private static final SnapshotCheckpointRowMapper SNAPSHOT_CHECKPOINT_ROW_MAPPER =
32	            new SnapshotCheckpointRowMapper();
33	
34	    private final JdbcTemplate jdbcTemplate;
35	
36	    public RaceRepository(JdbcTemplate jdbcTemplate) {
37	        this.jdbcTemplate = jdbcTemplate;
38	    }
39	
40	    /** 按ID查询赛事。 */
41	    public Optional<RaceRow> findRace(String raceId) {
42	        return jdbcTemplate
43	                .query("SELECT race_id, version, status, created_at FROM race WHERE race_id = ?",
44	                        RACE_ROW_MAPPER, raceId)
45	                .stream()
46	                .findFirst();
47	    }
48	
49	    /**
50	     * 行锁方式查询赛事：获取 race 行写锁并持有到事务提交/回滚。
51	     * 写操作据此与其它写者在读取任何依赖数据之前先串行化，避免 READ_COMMITTED 下
52	     * “先读到旧版本、后读到他人已提交明细”造成的误判（如分段重复误报422）。
53	     */
54	    public Optional<RaceRow> findRaceForUpdate(String raceId) {
55	        return jdbcTemplate
56	                .query("SELECT race_id, version, status, created_at FROM race WHERE race_id = ? FOR UPDATE",
57	                        RACE_ROW_MAPPER, raceId)
58	                .stream()
59	                .findFirst();
60	    }
61	
62	    /** 查询赛事下全部选手，按参赛号字典序排列。 */
63	    public List<RunnerRow> findRunners(String raceId) {
64	        return jdbcTemplate.query(
65	                "SELECT id, race_id, bib, finish_time_ms, created_at, updated_at "
66	                        + "FROM runner WHERE race_id = ? ORDER BY bib",
67	                RUNNER_ROW_MAPPER, raceId);
68	    }
69	
70	    /** 按赛事与参赛号查询选手。 */
71	    public Optional<RunnerRow> findRunner(String raceId, String bib) {
72	        return jdbcTemplate
73	                .query("SELECT id, race_id, bib, finish_time_ms, created_at, updated_at "
74	                                + "FROM runner WHERE race_id = ? AND bib = ?",
75	                        RUNNER_ROW_MAPPER, raceId, bib)
76	                .stream()
77	                .findFirst();
78	    }
79	
80	    /** 查询赛事下全部处罚（含已撤销），按新增时间与处罚ID排列。 */
81	    public List<PenaltyRow> findPenalties(String raceId) {
82	        return jdbcTemplate.query(
83	                "SELECT penalty_id, race_id, bib, type, amount_ms, revoked, created_at, revoked_at "
84	                        + "FROM penalty WHERE race_id = ? ORDER BY created_at, penalty_id",
85	                PENALTY_ROW_MAPPER, raceId);
86	    }
87	
88	    /** 按全局处罚ID查询处罚。 */
89	    public Optional<PenaltyRow> findPenalty(String penaltyId) {
90	        return jdbcTemplate
91	                .query("SELECT penalty_id, race_id, bib, type, amount_ms, revoked, created_at, revoked_at "
92	                                + "FROM penalty WHERE penalty_id = ?",
93	                        PENALTY_ROW_MAPPER, penaltyId)
94	                .stream()
95	                .findFirst();
96	    }
97	
98	    /** 查询赛事的全部检查点，按顺序 position 升序排列；未配置时为空列表。 */
99	    public List<CheckpointRow> findCheckpoints(String raceId) {
100	        return jdbcTemplate.query(
101	                "SELECT race_id, checkpoint_code, position, created_at "
102	                        + "FROM checkpoint WHERE race_id = ? ORDER BY position",
103	                CHECKPOINT_ROW_MAPPER, raceId);
104	    }
105	
106	    /** 按赛事与代码查询检查点。 */
107	    public Optional<CheckpointRow> findCheckpoint(String raceId, String checkpointCode) {
108	        return jdbcTemplate
109	                .query("SELECT race_id, checkpoint_code, position, created_at "
110	                                + "FROM checkpoint WHERE race_id = ? AND checkpoint_code = ?",
111	                        CHECKPOINT_ROW_MAPPER, raceId, checkpointCode)
112	                .stream()
113	                .findFirst();
114	    }
115	
116	    /** 统计赛事下的分段记录总数（用于“尚无任何分段记录时才可配置检查点”）。 */
117	    public int countTimings(String raceId) {
118	        Integer count = jdbcTemplate.queryForObject(
119	                "SELECT COUNT(*) FROM checkpoint_timing WHERE race_id = ?",
120	                Integer.class, raceId);
121	        return count == null ? 0 : count;
122	    }
123	
124	    /** 查询某选手的全部分段记录，按 position 升序排列。 */
125	    public List<CheckpointTimingRow> findTimingsForRunner(String raceId, String bib) {
126	        return jdbcTemplate.query(
127	                "SELECT timing_id, race_id, bib, checkpoint_code, position, elapsed_millis, created_at "
128	                        + "FROM checkpoint_timing WHERE race_id = ? AND bib = ? ORDER BY position",
129	                CHECKPOINT_TIMING_ROW_MAPPER, raceId, bib);
130	    }
131	
132	    /** 查询赛事下全部分段记录（用于实时成绩与封榜计算）。 */
133	    public List<CheckpointTimingRow> findAllTimings(String raceId) {
134	        return jdbcTemplate.query(
135	                "SELECT timing_id, race_id, bib, checkpoint_code, position, elapsed_millis, created_at "
136	                        + "FROM checkpoint_timing WHERE race_id = ? ORDER BY bib, position",
137	                CHECKPOINT_TIMING_ROW_MAPPER, raceId);
138	    }
139	
140	    /** 按全局分段ID查询记录（用于 timingId 幂等重放）。 */
141	    public Optional<CheckpointTimingRow> findTiming(String timingId) {
142	        return jdbcTemplate
143	                .query("SELECT timing_id, race_id, bib, checkpoint_code, position, elapsed_millis, created_at "
144	                                + "FROM checkpoint_timing WHERE timing_id = ?",
145	                        CHECKPOINT_TIMING_ROW_MAPPER, timingId)
146	                .stream()
147	                .findFirst();
148	    }
149	
150	    /** 新增选手分段通过记录（全局唯一 timingId 与选手+检查点唯一键由数据库约束保证）。 */
151	    public void insertTiming(CheckpointTimingRow row) {
152	        jdbcTemplate.update(
153	                "INSERT INTO checkpoint_timing "
154	                        + "(timing_id, race_id, bib, checkpoint_code, position, elapsed_millis, created_at) "
155	                        + "VALUES (?, ?, ?, ?, ?, ?, ?)",
156	                row.timingId(), row.raceId(), row.bib(), row.checkpointCode(),
157	                row.position(), row.elapsedMillis(), row.createdAt());
158	    }
159	
160	    /** 一次性写入赛事检查点配置（配置后不可修改）。 */
161	    public void insertCheckpoints(List<CheckpointRow> rows) {
162	        jdbcTemplate.batchUpdate(
163	                "INSERT INTO checkpoint (race_id, checkpoint_code, position, created_at) "
164	                        + "VALUES (?, ?, ?, ?)",
165	                rows,
166	                rows.size(),
167	                (ps, row) -> {
168	                    ps.setString(1, row.raceId());
169	                    ps.setString(2, row.checkpointCode());
170	                    ps.setInt(3, row.position());
171	                    ps.setLong(4, row.createdAt());
172	                });
173	    }
174	
175	    /** 查询封榜快照（含全部条目与分段明细）；未封榜返回 empty。 */
176	    public Optional<SnapshotRow> findSnapshot(String raceId) {
177	        List<SnapshotRow> headers = jdbcTemplate.query(
178	                "SELECT race_id, version, sealed_at FROM result_snapshot WHERE race_id = ?",
179	                (rs, rowNum) -> new SnapshotRow(
180	                        rs.getString("race_id"),
181	                        rs.getInt("version"),
182	                        rs.getLong("sealed_at"),
183	                        List.of()),
184	                raceId);
185	        if (headers.isEmpty()) {
186	            return Optional.empty();
187	        }
188	        SnapshotRow header = headers.getFirst();
189	        List<SnapshotEntryRow> entryRows = jdbcTemplate.query(
190	                "SELECT race_id, bib, rank_no, status, finish_time_ms, penalty_ms, total_time_ms, "
191	                        + "display_order, checkpoint_count, covered_checkpoint_count "
192	                        + "FROM result_snapshot_entry WHERE race_id = ? ORDER BY display_order",
193	                SNAPSHOT_ENTRY_ROW_MAPPER, raceId);
194	        List<SnapshotCheckpointRow> checkpoints = jdbcTemplate.query(
195	                "SELECT race_id, bib, checkpoint_code, position, elapsed_millis, timing_id "
196	                        + "FROM result_snapshot_checkpoint WHERE race_id = ? "
197	                        + "ORDER BY bib, position",
198	                SNAPSHOT_CHECKPOINT_ROW_MAPPER, raceId);
199	        // 缺失检查点由明细表中 elapsed_millis 为 NULL 的行派生，保持展示顺序稳定。
200	        java.util.Map<String, List<String>> missingByBib = new java.util.LinkedHashMap<>();
201	        for (SnapshotCheckpointRow detail : checkpoints) {
202	            if (detail.elapsedMillis() == null) {
203	                missingByBib.computeIfAbsent(detail.bib(), key -> new java.util.ArrayList<>())
204	                        .add(detail.checkpointCode());
205	            }
206	        }
207	        List<SnapshotEntryRow> entries = entryRows.stream()
208	                .map(entry -> new SnapshotEntryRow(
209	                        entry.raceId(), entry.bib(), entry.rank(), entry.status(),
210	                        entry.finishTimeMs(), entry.penaltyMs(), entry.totalTimeMs(),
211	                        entry.displayOrder(), entry.checkpointCount(),
212	                        entry.coveredCheckpointCount(),
213	                        missingByBib.getOrDefault(entry.bib(), List.of())))
214	                .toList();
215	        return Optional.of(new SnapshotRow(header.raceId(), header.version(), header.sealedAt(),
216	                entries, checkpoints));
217	    }
218	
219	    /** 新建赛事，初始版本1、状态OPEN。 */
220	    public void insertRace(String raceId, long now) {
221	        jdbcTemplate.update(
222	                "INSERT INTO race (race_id, version, status, created_at) VALUES (?, 1, 'OPEN', ?)",
223	                raceId, now);
224	    }
225	
226	    /** 登记选手；finishTimeMs 为 null 表示计时缺失。 */
227	    public void insertRunner(String raceId, String bib, Long finishTimeMs, long now) {
228	        jdbcTemplate.update(
229	                "INSERT INTO runner (race_id, bib, finish_time_ms, created_at, updated_at) "
230	                        + "VALUES (?, ?, ?, ?, ?)",
231	                raceId, bib, finishTimeMs, now, now);
232	    }
233	
234	    /** 修订选手原始完赛耗时；返回受影响行数（0 表示选手不存在）。 */
235	    public int updateRunnerTiming(String raceId, String bib, Long finishTimeMs, long now) {
236	        return jdbcTemplate.update(
237	                "UPDATE runner SET finish_time_ms = ?, updated_at = ? WHERE race_id = ? AND bib = ?",
238	                finishTimeMs, now, raceId, bib);
239	    }
240	
241	    /** 新增处罚（不可覆盖历史）。 */
242	    public void insertPenalty(
243	            String penaltyId,
244	            String raceId,
245	            String bib,
246	            PenaltyType type,
247	            Long amountMs,
248	            long now) {
249	        jdbcTemplate.update(
250	                "INSERT INTO penalty "
251	                        + "(penalty_id, race_id, bib, type, amount_ms, revoked, created_at, revoked_at) "
252	                        + "VALUES (?, ?, ?, ?, ?, FALSE, ?, NULL)",
253	                penaltyId, raceId, bib, type.name(), amountMs, now);
254	    }
255	
256	    /** 撤销处罚，仅对当前未撤销的处罚生效；返回受影响行数。 */
257	    public int markPenaltyRevoked(String penaltyId, long now) {
258	        return jdbcTemplate.update(
259	                "UPDATE penalty SET revoked = TRUE, revoked_at = ? WHERE penalty_id = ? AND revoked = FALSE",
260	                now, penaltyId);
261	    }
262	
263	    /**
264	     * 条件推进版本：仅当赛事仍为 OPEN 且版本等于 expectedVersion 时加一。
265	     *
266	     * @return 受影响行数；0 表示赛事不存在、已封榜或版本已被其他写操作推进
267	     */
268	    public int bumpVersionIfOpen(String raceId, int expectedVersion) {
269	        return jdbcTemplate.update(
