package com.example.starter.race.api;

import java.util.List;

/**
 * 追逐赛当前状态响应（配置、轨迹版本与当前裁定）。
 *
 * @param raceId        赛事ID
 * @param version       当前赛事版本号
 * @param pairs         已固定的追逐对（按序号升序）
 * @param trajectories  当前轨迹（按参赛号字典序）
 * @param adjudications 当前裁定（按追逐对序号升序）
 */
public record PursuitStateResponse(
        String raceId,
        int version,
        List<PursuitPairResponse> pairs,
        List<TrajectoryResponse> trajectories,
        List<AdjudicationResponse> adjudications
) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 追逐赛封榜快照响应：冻结的追逐对裁定（交会分数）与完整轨迹点。
 *
 * @param raceId   赛事ID
 * @param version  封榜后的赛事版本号
 * @param sealedAt 封榜时间，Unix毫秒时间戳
 * @param pairs    冻结的追逐对与交会分数（按序号升序）
 * @param samples  冻结的完整轨迹点（按参赛号与采样序号升序）
 */
public record PursuitSnapshotResponse(
        String raceId,
        int version,
        long sealedAt,
        List<PursuitSnapshotPairResponse> pairs,
        List<PursuitSnapshotSampleResponse> samples
) {
}

package com.example.starter.race.api;

/**
 * 封榜冻结的轨迹采样点。
 *
 * @param bib        选手参赛号
 * @param seq        采样序号，从1连续递增；隐含起点固定为(0,0)不占序号
 * @param timeMs     从起跑起的时刻（毫秒）
 * @param distanceMm 累计前进距离（毫米）
 */
public record PursuitSnapshotSampleResponse(
        String bib,
        int seq,
        long timeMs,
        long distanceMm
) {
}

